#include "core/push_plan.h"

typedef struct {
  int first_y, last_y, x0, x1;
  int64_t rows, pixels;
} Group;

static int64_t group_cost(const Group *g) {
  int64_t h = g->last_y - g->first_y + 1, w = g->x1 - g->x0 + 1;
  return PUSH_FLUSH_NS + h * PUSH_FLUSH_ROW_NS + w * h * PUSH_FLUSH_PIXEL_NS +
         g->rows * PUSH_CALL_NS + g->pixels * PUSH_COPY_PIXEL_NS;
}

static Group merge(const Group *a, const Group *b) {
  Group g = *a;
  g.last_y = b->last_y;
  if (b->x0 < g.x0) g.x0 = b->x0;
  if (b->x1 > g.x1) g.x1 = b->x1;
  g.rows += b->rows;
  g.pixels += b->pixels;
  return g;
}

PushKind push_plan(Canvas *c, PushRow *rows, int *count, bool use_disc) {
  int n = 0;
  int64_t total_ns = 0;
  Group cur = {0};
  for (int y = 0; y < c->h; y++) {
    int x0, x1;
    if (!canvas_dirty_row(c, y, &x0, &x1)) continue;
    if (use_disc) {
      int v0, v1;
      if (!canvas_visible_span(c, y, &v0, &v1)) continue;
      if (x0 < v0) x0 = v0;
      if (x1 > v1) x1 = v1;
      if (x0 > x1) continue;
    }
    Group one = {y, y, x0, x1, 1, x1 - x0 + 1};
    if (n == 0) {
      cur = one;
    } else {
      Group merged = merge(&cur, &one);
      if (group_cost(&merged) <= group_cost(&cur) + group_cost(&one)) {
        cur = merged;
      } else {
        rows[n - 1].end_of_group = true;
        total_ns += group_cost(&cur);
        cur = one;
      }
    }
    rows[n++] = (PushRow){y, x0, x1, false};
  }
  canvas_clear_dirty(c);
  *count = 0;
  if (n == 0) return PUSH_NONE;
  rows[n - 1].end_of_group = true;
  total_ns += group_cost(&cur);
  if (total_ns >= (int64_t)c->w * c->h * PUSH_PIXEL_NS) return PUSH_ALL;
  *count = n;
  return PUSH_ROWS;
}

int push_present(Canvas *c, PushRow *scratch, const PushSink *sink, bool use_disc) {
  int count;
  switch (push_plan(c, scratch, &count, use_disc)) {
    case PUSH_NONE:
      return 0;
    case PUSH_ALL:
      sink->all(sink->ctx);
      return c->h;
    default:
      for (int i = 0; i < count; i++) {
        if (i == 0 || scratch[i - 1].end_of_group) sink->begin(sink->ctx);
        sink->row(sink->ctx, scratch[i].y, scratch[i].x0, scratch[i].x1);
        if (scratch[i].end_of_group) sink->end(sink->ctx);
      }
      return count;
  }
}
/* Builds the unmodified deluxe.c with resources that suit the shim. Its
 * `transparent` default draws through colour-plane masks, which an RGB565
 * canvas cannot do, and its `doubleBuffer` default draws into two pixmaps,
 * which would cost 868 KB and a full-frame copy each frame.
 *
 * Its circles are 50 pixels wide arcs up to 700 across. The shim strokes an
 * arc as a polyline of about a thousand wide segments, each filled a row at a
 * time, and that was 94% of a frame (2 to 5 fps); stroke_circle fills the same
 * ring in two spans a row. */
#include "screenhack.h"
#include "x11shim/stroke.h"

static int deluxe_draw_arc(Display *dpy, Drawable d, GC gc, int x, int y,
                           unsigned int w, unsigned int h, int angle1,
                           int angle2) {
  if (gc->line_width > 1 && w == h && (angle2 >= 360 * 64 || angle2 <= -360 * 64)) {
    stroke_circle(dpy->canvas, gc, x, y, w);
    return 0;
  }
  return XDrawArc(dpy, d, gc, x, y, w, h, angle1, angle2);
}

#define XDrawArc deluxe_draw_arc

/* Upstream's translucent path draws each shape at alpha 0xCC of 0xFF; 26 of 32
 * is the same weight. Only the throbbers' GCs set a line width. */
#define DELUXE_ALPHA 26
static GC deluxe_create_gc(Display *dpy, Drawable d, unsigned long mask,
                           XGCValues *v) {
  GC gc = XCreateGC(dpy, d, mask, v);
  if (gc && (mask & GCLineWidth)) gc->alpha = DELUXE_ALPHA;
  return gc;
}

#define XCreateGC deluxe_create_gc

#undef XSCREENSAVER_MODULE
#define XSCREENSAVER_MODULE(CLASS, PREFIX)

#include "deluxe/deluxe.c"

static const char *const kDeluxeOverrides[] = {"*transparent: False",
                                               "*doubleBuffer: False", NULL};

const HackEntry deluxe_hack = {"Deluxe", deluxe_defaults, deluxe_init,
                               deluxe_draw, deluxe_free, NULL,
                               kDeluxeOverrides};
