static ButtonLatch latchA, latchB;

static void buttonTask(void *) {
  for (;;) {
    uint32_t now = millis();
    button_latch_sample(&latchA, gpio_get_level(kPinButtonA) == 0, now);
    button_latch_sample(&latchB, gpio_get_level(kPinButtonB) == 0, now);
    vTaskDelay(pdMS_TO_TICKS(kButtonPollMs));
  }
}

static Canvas canvas;
static HackRunner *runner;
static Overlay overlay;
static Rotation rotation;
static uint32_t frames;
static uint32_t statsAt;
static uint32_t stepUs, pushUs, syncUs, waitUs, rowsPushed;
static uint32_t lastSyncUs; /* the TE wait of the latest present() */
static PushRow pushRows[kSize];

/* The panel's tearing-effect line (OLED_TE, GPIO 38) pulses once a refresh, 60
#endif

static void hackStarted() {
  const HackEntry *hack = g_hacks[runner_index(runner)];
  const bool keep32 = hack->sync_to_refresh || hack->dcache_line32;
  dcache_set_line_size(keep32 ? 32 : kBulkLineBytes);
  uint32_t now = millis();
  overlay_hack_started(&overlay, now);
  rotation_reset(&rotation, now);
  resetStats();
}

/* Returns true if a button switched hacks. */
static bool pollButtons() {
  bool switched = false;
  uint32_t pressedAt = 0;
  if (button_latch_take(&latchA, &pressedAt)) {
    runner_next(runner);
    switched = true;
  }
  if (button_latch_take(&latchB, &pressedAt)) {
    runner_prev(runner);
    switched = true;
  }
  if (switched) {
    Serial.printf("switch -> %s press_waited=%ums heap=%u psram=%u\n",
                  g_hacks[runner_index(runner)]->name,
                  (unsigned)(millis() - pressedAt),
                  (unsigned)ESP.getFreeHeap(),
                  (unsigned)heap_caps_get_free_size(MALLOC_CAP_SPIRAM));
    hackStarted();
  }
  return switched;
}

/* Returns true if the timer moved on to the next hack. */
static bool pollRotation() {
  if (!rotation_due(&rotation, millis())) return false;
  runner_next(runner);
  Serial.printf("rotate -> %s heap=%u psram=%u\n",
                g_hacks[runner_index(runner)]->name, (unsigned)ESP.getFreeHeap(),
                (unsigned)heap_caps_get_free_size(MALLOC_CAP_SPIRAM));
  hackStarted();
  return true;
}

/* A tap anywhere cycles the readout: nothing, name badge, QR code, fps,
 * battery. Call
 * right after M5.update(), which is the only place the touch edge is
 * recorded. */
static void pollTouch() {
  if (M5.Touch.getDetail().wasPressed()) overlay_cycle_info(&overlay);
}

/* The fuel gauge is read over I2C through the power chip, which can fail the
 * first transaction after idle, so read it every 30 s, not every frame. A
 * failed read is negative and the overlay keeps the last good level. */
static void pollBattery() {
  static uint32_t lastReadMs;
  static bool readOnce;
  uint32_t now = millis();
  if (readOnce && now - lastReadMs < kBatteryEveryMs) return;
  readOnce = true;
  lastReadMs = now;
  overlay_set_battery(&overlay, M5.Power.getBatteryLevel());
}

#ifdef GL_PROFILE
/* Issue #43: cycles per access to a new 32-byte cache line in PSRAM, taking
 * the lines in address order (line_rmw) and down columns, a row apart, as a
 * small triangle's rows are (col_rmw, col_read); internal RAM for scale.
 * Each walk runs twice, so the XOR leaves the buffer as it was. */
static uint32_t memWalk(volatile uint16_t *buf, int cols, int rows, int stride) {
  uint32_t start = glshim_prof_now();
  for (int pass = 0; pass < 2; pass++)
    for (int x = 0; x < cols; x++)
      for (int y = 0; y < rows; y++) buf[(size_t)y * stride + x * 16] ^= 1;
  return (glshim_prof_now() - start) / (2u * cols * rows);
}

static void memBench(uint16_t *psram) {
  uint32_t seq = memWalk(psram, 1, kSize * kSize / 16, 16);
  const int cols = kSize / 16; /* x * 16 stays inside the row */
  uint32_t col = memWalk(psram, cols, kSize, kSize);
  volatile uint16_t *b = psram;
  uint32_t sum = 0, start = glshim_prof_now();
  for (int x = 0; x < cols; x++)
    for (int y = 0; y < kSize; y++) sum += b[(size_t)y * kSize + x * 16];
  uint32_t colRead = (glshim_prof_now() - start) / ((uint32_t)cols * kSize);
  (void)sum;
  uint16_t *internal = (uint16_t *)heap_caps_malloc(16384, MALLOC_CAP_INTERNAL | MALLOC_CAP_8BIT);
  uint32_t inner = internal ? memWalk(internal, 1, 512, 16) : 0;
  free(internal);
  Serial.printf("membench psram_line_rmw=%u psram_col_rmw=%u psram_col_read=%u internal=%u cycles\n",
                (unsigned)seq, (unsigned)col, (unsigned)colRead, (unsigned)inner);
}
#endif

void setup() {
  auto cfg = M5.config();
  M5.begin(cfg);
  Serial.begin(115200);
#ifdef PSRAM_BENCH
  delay(3000);
  psram_bench::run();
  for (;;) delay(1000);
#endif
  M5.Display.setSwapBytes(false);
#ifdef HAVE_GRAB_IMAGE
  xshim_set_grab_image(grab_image_blob, sizeof(grab_image_blob));
#endif
  xshim_set_font(&special_elite_font);
  teInit();

  button_latch_init(&latchA, kButtonSettleMs);
  button_latch_init(&latchB, kButtonSettleMs);
  xTaskCreatePinnedToCore(buttonTask, "buttons", 2048, nullptr, 2, nullptr, 0);

  if (canvas_init(&canvas, kSize, kSize, ps_malloc) != 0)
    halt("PSRAM alloc failed");
  if (canvas_set_disc(&canvas, malloc) != 0) halt("disc alloc failed");
#ifdef GL_PROFILE
  memBench(canvas.px);
#endif

